const DELIVERY_FEE = 500;

// ─── HELPERS ─────────────────────────────────────────────────────────────────

const fmt = (n) => "₦" + Number(n).toLocaleString();

// ─── COMPONENTS ──────────────────────────────────────────────────────────────

function Logo() {
  return (
    <span style={{ fontWeight: 900, fontSize: 22, letterSpacing: -0.5 }}>
      <span style={{ color: "#fff" }}>FLASH</span>
      <span style={{ color: "#FF6B00" }}>DROP</span><span style={{ color: "#FF6B00", fontSize: 13 }}> ⚡</span>
    </span>
  );
}

function Badge({ children, color = "#FF6B00" }) {
  return (
    <span style={{
      background: color + "22", color,
      borderRadius: 20, padding: "2px 10px",
      fontSize: 11, fontWeight: 700, letterSpacing: 0.3
    }}>{children}</span>
  );
}

function StarRating({ rating }) {
  return <span style={{ color: "#FF6B00", fontSize: 12, fontWeight: 700 }}>★ {rating}</span>;
}

// ─── SCREENS ─────────────────────────────────────────────────────────────────

// Build a flat list of all menu items across all restaurants for search
const ALL_MENU_ITEMS = RESTAURANTS.flatMap(r =>
  r.menu.map(item => ({ ...item, restaurant: r }))
);

function SearchResults({ query, onAddToCart, cart, onGoToRestaurant }) {
  const q = query.toLowerCase().trim();
  const results = ALL_MENU_ITEMS.filter(i =>
    i.name.toLowerCase().includes(q) || i.desc.toLowerCase().includes(q)
  );

  if (!q) return null;

  return (
    <div style={{ padding: "12px 16px", display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ fontWeight: 700, fontSize: 13, color: "#999" }}>
        {results.length === 0 ? "No results found" : `${results.length} result${results.length > 1 ? "s" : ""} for "${query}"`}
      </div>
      {results.map((item, idx) => {
        const qty = cart[item.id]?.qty || 0;
        return (
          <div key={idx} style={{
            background: "#fff", borderRadius: 14, padding: "14px 16px",
            boxShadow: "0 2px 10px rgba(0,0,0,0.07)",
            display: "flex", justifyContent: "space-between", alignItems: "center"
          }}>
            <div style={{
              width: 64, height: 64, borderRadius: 12, flexShrink: 0,
              overflow: "hidden", background: "#FFF3E8",
              display: "flex", alignItems: "center", justifyContent: "center"
            }}>
              {item.img
                ? <img src={item.img} alt={item.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                : <span style={{ fontSize: 26 }}>{item.restaurant.emoji}</span>}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 800, fontSize: 14, color: "#1A1A1A" }}>{item.name}</div>
              <div style={{ color: "#999", fontSize: 12, marginTop: 2 }}>{item.desc}</div>
              {/* Restaurant tag */}
              <button onClick={() => onGoToRestaurant(item.restaurant)} style={{
                background: "#FFF3E8", border: "none", borderRadius: 8,
                padding: "3px 8px", marginTop: 6, cursor: "pointer",
                display: "inline-flex", alignItems: "center", gap: 4, maxWidth: "100%"
              }}>
                <span style={{ fontSize: 13 }}>{item.restaurant.emoji}</span>
                <span style={{
                  fontSize: 11, fontWeight: 700, color: "#FF6B00",
                  overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap"
                }}>{item.restaurant.name}</span>
                {!item.restaurant.isOpen && <span style={{ fontSize: 10, color: "#999", flexShrink: 0 }}>• Closed</span>}
              </button>
              <div style={{ color: "#FF6B00", fontWeight: 800, fontSize: 15, marginTop: 6 }}>{fmt(item.price)}</div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
              {qty > 0 && (
                <>
                  <button onClick={() => onAddToCart(item, -1)} style={{
                    width: 30, height: 30, borderRadius: "50%", border: "2px solid #FF6B00",
                    background: "#fff", color: "#FF6B00", fontWeight: 900, fontSize: 18,
                    cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
                  }}>−</button>
                  <span style={{ fontWeight: 800, fontSize: 15, minWidth: 16, textAlign: "center" }}>{qty}</span>
                </>
              )}
              <button
                onClick={() => item.restaurant.isOpen && onAddToCart(item, 1)}
                style={{
                  width: 30, height: 30, borderRadius: "50%", border: "none",
                  background: item.restaurant.isOpen ? "#FF6B00" : "#ccc",
                  color: "#fff", fontWeight: 900, fontSize: 18,
                  cursor: item.restaurant.isOpen ? "pointer" : "not-allowed",
                  display: "flex", alignItems: "center", justifyContent: "center"
                }}>+</button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function FoodSlider() {
  const items = [
    { img: IMG_JOLLOF_CHICKEN_PLATE, label: "Jollof & grill" },
    { img: IMG_SUYA_SKEWERS, label: "Suya, off the coal" },
    { img: IMG_VEG_SOUP_FUFU, label: "Native soups" },
    { img: IMG_PIZZA_PULL, label: "Stone-oven pizza" },
    { img: IMG_BEEF_WRAP_BOARD, label: "Loaded wraps" },
    { img: IMG_BERRY_PARFAIT_LAYERS, label: "Parfaits & sweets" },
  ];
  return (
    <div style={{
      display: "flex", gap: 10, overflowX: "auto", padding: "14px 16px 4px",
      scrollSnapType: "x proximity", WebkitOverflowScrolling: "touch"
    }}>
      {items.map((it, i) => (
        <div key={i} style={{
          flexShrink: 0, width: 104, scrollSnapAlign: "start",
          display: "flex", flexDirection: "column", gap: 6
        }}>
          <div style={{
            width: 104, height: 104, borderRadius: 18, overflow: "hidden",
            boxShadow: "0 3px 14px rgba(0,0,0,0.18)"
          }}>
            <img src={it.img} alt={it.label} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>
          <div style={{ color: "#fff", fontSize: 11.5, fontWeight: 700, lineHeight: 1.25 }}>{it.label}</div>
        </div>
      ))}
    </div>
  );
}

function HomeScreen({ onOrder, cart, onAddSearchItem, onRemoveSearchItem }) {
  const [filter, setFilter] = useState("all");
  const [query, setQuery] = useState("");
  const isSearching = query.trim().length > 0;

  const filtered = RESTAURANTS.filter(r =>
    filter === "all" ? true :
    filter === "fast_food" ? r.category === "fast_food" :
    filter === "cafe" ? r.category === "cafe" :
    r.category === "local_meals"
  );

  const handleSearchAdd = (item, delta) => {
    if (delta > 0) onAddSearchItem(item);
    else onRemoveSearchItem(item);
  };

  return (
    <div style={{ paddingBottom: 80 }}>
      {/* Hero Header */}
      <div style={{
        background: "linear-gradient(135deg, #1A1A1A 0%, #2d2d2d 100%)",
        padding: "20px 16px 24px",
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <Logo />
          <div style={{
            background: "#FF6B00", borderRadius: 20, padding: "4px 12px",
            fontSize: 12, color: "#fff", fontWeight: 700
          }}>
            📍 UNIZIK, Awka
          </div>
        </div>
        <div style={{ color: "#fff", fontSize: 22, fontWeight: 800, lineHeight: 1.2, marginBottom: 4 }}>
          UNIZIK's fastest kitchen run
        </div>
        <div style={{ color: "#aaa", fontSize: 13, marginBottom: 14 }}>
          From Ifite gate to your hostel in 15 — flat ₦500 delivery, no haggling
        </div>

        <FoodSlider />

        {/* Search bar */}
        <div style={{ position: "relative", marginTop: 14 }}>
          <span style={{
            position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)",
            fontSize: 16, pointerEvents: "none"
          }}>🔍</span>
          <input
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="Search meat pie, jollof rice, shawarma..."
            style={{
              width: "100%", background: "#fff", border: "none",
              borderRadius: 12, padding: "13px 40px 13px 42px",
              fontSize: 14, outline: "none", fontFamily: "inherit",
              boxSizing: "border-box", color: "#1A1A1A"
            }}
          />
          {query.length > 0 && (
            <button onClick={() => setQuery("")} style={{
              position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)",
              background: "#ddd", border: "none", borderRadius: "50%",
              width: 22, height: 22, cursor: "pointer", fontSize: 12,
              display: "flex", alignItems: "center", justifyContent: "center", color: "#555"
            }}>✕</button>
          )}
        </div>
      </div>

      {/* Search Results */}
      {isSearching ? (
        <SearchResults
          query={query}
          cart={cart}
          onAddToCart={handleSearchAdd}
          onGoToRestaurant={(r) => { setQuery(""); onOrder(r); }}
        />
      ) : (
        <>
          {/* Filter tabs */}
          <div style={{ display: "flex", gap: 8, padding: "16px 16px 8px", overflowX: "auto" }}>
            {[["all", "🍽 All"], ["fast_food", "🌯 Fast Food"], ["local_meals", "🍲 Local"], ["cafe", "☕ Cafe"]].map(([val, label]) => (
              <button key={val} onClick={() => setFilter(val)} style={{
                border: "none", borderRadius: 20, padding: "8px 16px",
                background: filter === val ? "#FF6B00" : "#f0f0f0",
                color: filter === val ? "#fff" : "#555",
                fontWeight: 700, fontSize: 13, whiteSpace: "nowrap", cursor: "pointer"
              }}>{label}</button>
            ))}
          </div>

          {/* Restaurant Cards */}
          <div style={{ padding: "8px 16px", display: "flex", flexDirection: "column", gap: 12 }}>
            {filtered.map(r => (
              <button key={r.id} onClick={() => r.isOpen && onOrder(r)}
                style={{
                  background: "#fff", borderRadius: 16, border: "none",
                  padding: 16, textAlign: "left", cursor: r.isOpen ? "pointer" : "not-allowed",
                  boxShadow: "0 2px 12px rgba(0,0,0,0.08)",
                  opacity: r.isOpen ? 1 : 0.6, width: "100%"
                }}>
                <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
                  <div style={{
                    width: 56, height: 56, borderRadius: 14,
                    background: "#FFF3E8", display: "flex", alignItems: "center",
                    justifyContent: "center", fontSize: 28, flexShrink: 0, overflow: "hidden"
                  }}>
                    {r.img
                      ? <img src={r.img} alt={r.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      : r.emoji}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
                      <div style={{
                        fontWeight: 800, fontSize: 15, color: "#1A1A1A",
                        overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap"
                      }}>{r.name}</div>
                      {!r.isOpen && <Badge color="#999">Closed</Badge>}
                      {r.isOpen && <StarRating rating={r.rating} />}
                    </div>
                    <div style={{ color: "#777", fontSize: 13, marginTop: 2 }}>{r.desc}</div>
                    <div style={{ display: "flex", gap: 8, marginTop: 8, alignItems: "center" }}>
                      <Badge color="#FF6B00">⏱ {r.time}</Badge>
                      <Badge color="#22C55E">🛵 {fmt(DELIVERY_FEE)} delivery</Badge>
                    </div>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function MenuScreen({ restaurant, cart, onAdd, onRemove, onBack, onCheckout }) {
  const totalItems = Object.values(cart).reduce((s, i) => s + i.qty, 0);
  const subtotal = Object.values(cart).reduce((s, i) => s + i.price * i.qty, 0);

  return (
    <div style={{ paddingBottom: 120 }}>
      {/* Header */}
      <div style={{
        background: "linear-gradient(135deg, #1A1A1A, #2d2d2d)",
        padding: "16px 16px 24px"
      }}>
        <button onClick={onBack} style={{
          background: "rgba(255,255,255,0.15)", border: "none", borderRadius: 10,
          color: "#fff", padding: "8px 14px", cursor: "pointer", fontSize: 13, fontWeight: 700, marginBottom: 12
        }}>← Back</button>
        <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <div style={{
            width: 52, height: 52, borderRadius: 14,
            background: "#FFF3E8", display: "flex", alignItems: "center",
            justifyContent: "center", fontSize: 26, overflow: "hidden", flexShrink: 0
          }}>
            {restaurant.img
              ? <img src={restaurant.img} alt={restaurant.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              : restaurant.emoji}
          </div>
          <div style={{ minWidth: 0 }}>
            <div style={{ color: "#fff", fontWeight: 900, fontSize: 20 }}>{restaurant.name}</div>
            <div style={{ color: "#aaa", fontSize: 13 }}>{restaurant.desc}</div>
          </div>
        </div>
      </div>

      {/* Menu */}
      <div style={{ padding: "16px 16px 0" }}>
        <div style={{ fontWeight: 800, fontSize: 16, color: "#1A1A1A", marginBottom: 12 }}>Menu</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {restaurant.menu.map(item => {
            const qty = cart[item.id]?.qty || 0;
            return (
              <div key={item.id} style={{
                background: "#fff", borderRadius: 14, padding: "14px 16px",
                boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
                display: "flex", gap: 12, justifyContent: "space-between", alignItems: "center"
              }}>
                {item.img && (
                  <div style={{
                    width: 60, height: 60, borderRadius: 12, flexShrink: 0,
                    overflow: "hidden", background: "#FFF3E8"
                  }}>
                    <img src={item.img} alt={item.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  </div>
                )}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 700, fontSize: 14, color: "#1A1A1A" }}>{item.name}</div>
                  <div style={{ color: "#999", fontSize: 12, marginTop: 2 }}>{item.desc}</div>
                  <div style={{ color: "#FF6B00", fontWeight: 800, fontSize: 15, marginTop: 4 }}>{fmt(item.price)}</div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
                  {qty > 0 && (
                    <>
                      <button onClick={() => onRemove(item)} style={{
                        width: 30, height: 30, borderRadius: "50%", border: "2px solid #FF6B00",
                        background: "#fff", color: "#FF6B00", fontWeight: 900, fontSize: 18,
                        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
                      }}>−</button>
                      <span style={{ fontWeight: 800, fontSize: 15, minWidth: 16, textAlign: "center" }}>{qty}</span>
                    </>
                  )}
                  <button onClick={() => onAdd(item)} style={{
                    width: 30, height: 30, borderRadius: "50%", border: "none",
                    background: "#FF6B00", color: "#fff", fontWeight: 900, fontSize: 18,
                    cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
                  }}>+</button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Cart bar */}
      {totalItems > 0 && (
        <div style={{
          position: "fixed", bottom: 80, left: 0, right: 0, padding: "0 16px"
        }}>
          <button onClick={onCheckout} style={{
            width: "100%", background: "#FF6B00", border: "none",
            borderRadius: 16, padding: "16px 20px", color: "#fff",
            display: "flex", justifyContent: "space-between", alignItems: "center",
            cursor: "pointer", boxShadow: "0 4px 20px rgba(255,107,0,0.4)"
          }}>
            <div style={{
              background: "rgba(255,255,255,0.25)", borderRadius: 8,
              padding: "2px 10px", fontWeight: 800, fontSize: 14
            }}>{totalItems} item{totalItems > 1 ? "s" : ""}</div>
            <span style={{ fontWeight: 800, fontSize: 15 }}>View Cart</span>
            <span style={{ fontWeight: 800, fontSize: 15 }}>{fmt(subtotal)}</span>
          </button>
        </div>
      )}
    </div>
  );
}

function CartScreen({ cart, restaurant, onBack, onPlaceOrder }) {
  const [address, setAddress] = useState("");
  const items = Object.values(cart).filter(i => i.qty > 0);
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const total = subtotal + DELIVERY_FEE;

  return (
    <div style={{ paddingBottom: 100 }}>
      <div style={{ background: "#1A1A1A", padding: "16px 16px 20px" }}>
        <button onClick={onBack} style={{
          background: "rgba(255,255,255,0.15)", border: "none", borderRadius: 10,
          color: "#fff", padding: "8px 14px", cursor: "pointer", fontSize: 13, fontWeight: 700, marginBottom: 12
        }}>← Back</button>
        <div style={{ color: "#fff", fontWeight: 900, fontSize: 20 }}>Your Cart</div>
        <div style={{ color: "#aaa", fontSize: 13 }}>{restaurant?.name}</div>
      </div>

      <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 10 }}>
        {items.map(item => (
          <div key={item.id} style={{
            background: "#fff", borderRadius: 14, padding: "14px 16px",
            boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
            display: "flex", gap: 12, alignItems: "center", justifyContent: "space-between"
          }}>
            <div style={{ display: "flex", gap: 12, alignItems: "center", minWidth: 0 }}>
              {item.img && (
                <div style={{
                  width: 44, height: 44, borderRadius: 10, flexShrink: 0,
                  overflow: "hidden", background: "#FFF3E8"
                }}>
                  <img src={item.img} alt={item.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                </div>
              )}
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 14 }}>{item.name}</div>
                <div style={{ color: "#999", fontSize: 12 }}>× {item.qty}</div>
              </div>
            </div>
            <div style={{ fontWeight: 800, color: "#FF6B00", flexShrink: 0 }}>{fmt(item.price * item.qty)}</div>
          </div>
        ))}

        {/* Delivery address */}
        <div style={{ background: "#fff", borderRadius: 14, padding: 16, boxShadow: "0 2px 8px rgba(0,0,0,0.06)" }}>
          <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 8 }}>📍 Delivery Address</div>
          <input
            value={address}
            onChange={e => setAddress(e.target.value)}
            placeholder="E.g. Block C, Room 14, Hostel 2"
            style={{
              width: "100%", border: "1.5px solid #eee", borderRadius: 10,
              padding: "10px 12px", fontSize: 13, outline: "none",
              boxSizing: "border-box", fontFamily: "inherit"
            }}
          />
        </div>

        {/* Summary */}
        <div style={{ background: "#fff", borderRadius: 14, padding: 16, boxShadow: "0 2px 8px rgba(0,0,0,0.06)" }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
            <span style={{ color: "#777", fontSize: 14 }}>Subtotal</span>
            <span style={{ fontWeight: 700 }}>{fmt(subtotal)}</span>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
            <span style={{ color: "#777", fontSize: 14 }}>Delivery fee 🎉 Promo</span>
            <span style={{ fontWeight: 700, color: "#22C55E" }}>{fmt(DELIVERY_FEE)}</span>
          </div>
          <div style={{ height: 1, background: "#f0f0f0", marginBottom: 12 }} />
          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <span style={{ fontWeight: 800, fontSize: 16 }}>Total</span>
            <span style={{ fontWeight: 900, fontSize: 18, color: "#FF6B00" }}>{fmt(total)}</span>
          </div>
        </div>
      </div>

      {/* Place Order */}
      <div style={{ position: "fixed", bottom: 80, left: 0, right: 0, padding: "0 16px" }}>
        <button
          onClick={() => address.trim() && onPlaceOrder({ items, subtotal, total, address })}
          style={{
            width: "100%", background: address.trim() ? "#FF6B00" : "#ccc",
            border: "none", borderRadius: 16, padding: 18,
            color: "#fff", fontWeight: 800, fontSize: 16,
            cursor: address.trim() ? "pointer" : "not-allowed",
            boxShadow: address.trim() ? "0 4px 20px rgba(255,107,0,0.4)" : "none"
          }}
        >
          Pay {fmt(total)} →
        </button>
      </div>
    </div>
  );
}

