          border: "none", borderRadius: 14, padding: 18,
          color: "#fff", fontWeight: 800, fontSize: 16,
          cursor: desc && pickup ? "pointer" : "not-allowed",
          boxShadow: desc && pickup ? "0 4px 20px rgba(255,107,0,0.4)" : "none"
