function HotelsScreen() {
  const [selected, setSelected] = useState(null);
  const [room, setRoom] = useState(null);
  const [checkin, setCheckin] = useState("");
  const [checkout, setCheckout] = useState("");
  const [step, setStep] = useState("list");

  if (step === "confirm") {
    return (
      <div style={{
        minHeight: "80vh", display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center",
        padding: 24, textAlign: "center"
      }}>
        <div style={{ fontSize: 64, marginBottom: 16 }}>🏨</div>
        <div style={{ fontWeight: 900, fontSize: 22, marginBottom: 8 }}>Booking Requested!</div>
        <div style={{ color: "#777", fontSize: 14, marginBottom: 16 }}>
          We'll call the hotel to confirm your room availability and get back to you.
        </div>
        <div style={{ background: "#FFF3E8", borderRadius: 14, padding: 16, width: "100%", textAlign: "left", marginBottom: 20 }}>
          <div style={{ fontWeight: 800, color: "#FF6B00", marginBottom: 8 }}>{selected?.name}</div>
          <div style={{ fontSize: 14, color: "#555", marginBottom: 4 }}>Room: {room?.type}</div>
          <div style={{ fontSize: 14, color: "#555", marginBottom: 4 }}>Check-in: {checkin}</div>
          <div style={{ fontSize: 14, color: "#555", marginBottom: 4 }}>Check-out: {checkout}</div>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#1A1A1A", marginTop: 8 }}>
            ₦{room?.price.toLocaleString()} / night
          </div>
        </div>
        <button onClick={() => { setStep("list"); setSelected(null); setRoom(null); setCheckin(""); setCheckout(""); }}
          style={{
            background: "#FF6B00", border: "none", borderRadius: 14,
            padding: "14px 32px", color: "#fff", fontWeight: 800,
            fontSize: 15, cursor: "pointer", width: "100%"
          }}>Back to Hotels</button>
      </div>
    );
  }

  if (step === "book" && selected) {
    return (
      <div style={{ padding: 16, paddingBottom: 100 }}>
        <button onClick={() => setStep("list")} style={{
          background: "#f0f0f0", border: "none", borderRadius: 10,
          padding: "8px 14px", cursor: "pointer", fontSize: 13, fontWeight: 700, marginBottom: 16
        }}>← Back</button>

        <div style={{
          background: "#1A1A1A", borderRadius: 16, padding: 20, marginBottom: 20,
          position: "relative", overflow: "hidden"
        }}>
          {selected.img && (
            <img src={selected.img} alt={selected.name} loading="lazy" style={{
              position: "absolute", inset: 0, width: "100%", height: "100%",
              objectFit: "cover", opacity: 0.35
            }} />
          )}
          <div style={{ position: "relative" }}>
            <div style={{ fontSize: 32, marginBottom: 8 }}>{selected.emoji}</div>
            <div style={{ color: "#fff", fontWeight: 900, fontSize: 20 }}>{selected.name}</div>
            <div style={{ color: "#aaa", fontSize: 13 }}>{selected.address}</div>
          </div>
        </div>

        <div style={{ fontWeight: 800, fontSize: 16, marginBottom: 12 }}>Select Room Type</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 20 }}>
          {selected.rooms.map(r => (
            <button key={r.id} onClick={() => setRoom(r)} style={{
              background: room?.id === r.id ? "#FFF3E8" : "#fff",
              border: room?.id === r.id ? "2px solid #FF6B00" : "2px solid #eee",
              borderRadius: 14, padding: 16, cursor: "pointer", textAlign: "left"
            }}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <div style={{ fontWeight: 800, fontSize: 15 }}>{r.type}</div>
                <div style={{ fontWeight: 900, color: "#FF6B00", fontSize: 15 }}>₦{r.price.toLocaleString()}/night</div>
              </div>
              <div style={{ color: "#777", fontSize: 13, marginTop: 4 }}>{r.desc}</div>
            </button>
          ))}
        </div>

        <div style={{ display: "flex", gap: 12, marginBottom: 20 }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 6 }}>Check-in</div>
            <input type="date" value={checkin} onChange={e => setCheckin(e.target.value)}
              style={{
                width: "100%", border: "1.5px solid #eee", borderRadius: 12,
                padding: "12px 14px", fontSize: 13, outline: "none",
                fontFamily: "inherit", boxSizing: "border-box"
              }} />
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 6 }}>Check-out</div>
            <input type="date" value={checkout} onChange={e => setCheckout(e.target.value)}
              style={{
                width: "100%", border: "1.5px solid #eee", borderRadius: 12,
                padding: "12px 14px", fontSize: 13, outline: "none",
                fontFamily: "inherit", boxSizing: "border-box"
              }} />
          </div>
        </div>

        <button
          onClick={() => room && checkin && checkout && setStep("confirm")}
          style={{
            width: "100%", background: room && checkin && checkout ? "#FF6B00" : "#ccc",
            border: "none", borderRadius: 14, padding: 18,
            color: "#fff", fontWeight: 800, fontSize: 16,
            cursor: room && checkin && checkout ? "pointer" : "not-allowed",
          }}>
          Request Booking →
        </button>
      </div>
    );
  }

  return (
    <div style={{ padding: 16, paddingBottom: 100 }}>
      <div style={{ background: "#1A1A1A", borderRadius: 16, padding: 20, marginBottom: 20 }}>
        <div style={{ color: "#FF6B00", fontWeight: 900, fontSize: 20, marginBottom: 4 }}>🏨 Hotels</div>
        <div style={{ color: "#aaa", fontSize: 13 }}>Book a room in Awka. We handle the call.</div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {HOTELS.map(h => (
          <button key={h.id} onClick={() => { setSelected(h); setStep("book"); }} style={{
            background: "#fff", borderRadius: 16, border: "none",
            padding: 16, textAlign: "left", cursor: "pointer",
            boxShadow: "0 2px 12px rgba(0,0,0,0.08)", width: "100%"
          }}>
            <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
              <div style={{
                width: 56, height: 56, borderRadius: 14, background: "#FFF3E8",
                display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: 28, flexShrink: 0, overflow: "hidden"
              }}>
                {h.img
                  ? <img src={h.img} alt={h.name} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  : h.emoji}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
                  <div style={{
                    fontWeight: 800, fontSize: 15,
                    overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap"
                  }}>{h.name}</div>
                  <StarRating rating={h.rating} />
                </div>
                <div style={{ color: "#777", fontSize: 13, marginTop: 2 }}>{h.desc}</div>
                <div style={{ color: "#999", fontSize: 12, marginTop: 2 }}>📍 {h.address}</div>
                <div style={{ marginTop: 8 }}>
                  <Badge color="#FF6B00">From ₦{Math.min(...h.rooms.map(r => r.price)).toLocaleString()}/night</Badge>
                </div>
              </div>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────

export default function App() {
  const [tab, setTab] = useState("food");
  const [screen, setScreen] = useState("home"); // home | menu | cart | confirm
  const [activeRestaurant, setActiveRestaurant] = useState(null);
  const [cart, setCart] = useState({});
  const [confirmedOrder, setConfirmedOrder] = useState(null);

  const addToCart = (item) => {
    setCart(c => ({
      ...c,
      [item.id]: { ...item, qty: (c[item.id]?.qty || 0) + 1 }
    }));
  };

  const removeFromCart = (item) => {
    setCart(c => {
      const qty = (c[item.id]?.qty || 0) - 1;
      if (qty <= 0) { const { [item.id]: _, ...rest } = c; return rest; }
      return { ...c, [item.id]: { ...item, qty } };
    });
  };

  const cartCount = Object.values(cart).reduce((s, i) => s + i.qty, 0);

  const handlePlaceOrder = (order) => {
    setConfirmedOrder(order);
    setScreen("confirm");
    setCart({});
  };

  const handleDone = () => {
    setScreen("home");
    setActiveRestaurant(null);
    setConfirmedOrder(null);
    setTab("food");
  };

  const renderScreen = () => {
    if (screen === "confirm") return <OrderConfirmScreen order={confirmedOrder} onDone={handleDone} />;
    if (screen === "cart") return (
      <CartScreen
        cart={cart}
        restaurant={activeRestaurant}
        onBack={() => setScreen("menu")}
        onPlaceOrder={handlePlaceOrder}
      />
    );
    if (screen === "menu" && activeRestaurant) return (
      <MenuScreen
        restaurant={activeRestaurant}
        cart={cart}
        onAdd={addToCart}
        onRemove={removeFromCart}
        onBack={() => { setScreen("home"); setActiveRestaurant(null); }}
        onCheckout={() => setScreen("cart")}
      />
    );

    if (tab === "food") return (
      <HomeScreen
        cart={cart}
        onOrder={(r) => { setActiveRestaurant(r); setScreen("menu"); }}
        onAddSearchItem={(item) => {
          // When adding from search, track which restaurant this item belongs to
          setActiveRestaurant(item.restaurant);
          addToCart(item);
        }}
        onRemoveSearchItem={(item) => removeFromCart(item)}
      />
    );
    if (tab === "errands") return <ErrandsScreen />;
    if (tab === "hotels") return <HotelsScreen />;
  };

  const showNav = screen === "home" || (screen !== "confirm" && screen !== "cart" && screen !== "menu");

  return (
    <div style={{
      maxWidth: 430, margin: "0 auto", minHeight: "100vh",
      background: "#F5F5F5", position: "relative",
      fontFamily: "'Segoe UI', system-ui, -apple-system, sans-serif"
    }}>
      <div style={{ minHeight: "calc(100vh - 64px)", overflowY: "auto" }}>
        {renderScreen()}
      </div>

      {/* Floating cart bar on home when items added via search */}
      {screen === "home" && cartCount > 0 && (
        <div style={{ position: "fixed", bottom: 72, left: "50%", transform: "translateX(-50%)", width: "100%", maxWidth: 430, padding: "0 16px", boxSizing: "border-box", zIndex: 99 }}>
          <button onClick={() => setScreen("cart")} style={{
            width: "100%", background: "#FF6B00", border: "none",
            borderRadius: 16, padding: "16px 20px", color: "#fff",
            display: "flex", justifyContent: "space-between", alignItems: "center",
            cursor: "pointer", boxShadow: "0 4px 20px rgba(255,107,0,0.4)"
          }}>
            <div style={{
              background: "rgba(255,255,255,0.25)", borderRadius: 8,
              padding: "2px 10px", fontWeight: 800, fontSize: 14
            }}>{cartCount} item{cartCount > 1 ? "s" : ""}</div>
            <span style={{ fontWeight: 800, fontSize: 15 }}>View Cart</span>
            <span style={{ fontWeight: 800, fontSize: 15 }}>{fmt(Object.values(cart).reduce((s, i) => s + i.price * i.qty, 0))}</span>
          </button>
        </div>
      )}

      {/* Bottom Nav */}
      {(screen === "home" || screen === "menu" || screen === "cart") && (
        <div style={{
          position: "fixed", bottom: 0, left: "50%", transform: "translateX(-50%)",
          width: "100%", maxWidth: 430,
          background: "#fff", borderTop: "1px solid #eee",
          display: "flex", height: 64, zIndex: 100
        }}>
          {[
            { key: "food", icon: "🍔", label: "Food" },
            { key: "errands", icon: "🛵", label: "Errands" },
            { key: "hotels", icon: "🏨", label: "Hotels" },
          ].map(t => (
            <button key={t.key} onClick={() => { setTab(t.key); setScreen("home"); setActiveRestaurant(null); }}
              style={{
                flex: 1, border: "none", background: "transparent",
                display: "flex", flexDirection: "column", alignItems: "center",
                justifyContent: "center", gap: 2, cursor: "pointer",
                color: tab === t.key && screen === "home" ? "#FF6B00" : "#999",
              }}>
              <span style={{ fontSize: 22 }}>{t.icon}</span>
              <span style={{
                fontSize: 11, fontWeight: tab === t.key && screen === "home" ? 800 : 500
              }}>{t.label}</span>
              {tab === t.key && screen === "home" && (
                <div style={{ width: 4, height: 4, borderRadius: "50%", background: "#FF6B00" }} />
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
